describe('Google Account Connection to User Profile', () => {
  beforeEach(() => {
    cy.visit('/profile');
  });

  it('should successfully connect Google account to user profile', () => {
    // Intercept Google OAuth redirect
    cy.intercept('GET', 'https://accounts.google.com/oosignin?client_id=*').as('googleAuth');

    // Click Google login button
    cy.get('[data-testid="google-login-button"]').click();

    // Wait for Google OAuth redirect
    cy.wait('@googleAuth');

    // Verify Google login modal appears
    cy.get('[data-testid="google-login-modal"]').should('be.visible');

    // Fill in Google credentials
    cy.get('[data-testid="google-email-input"]').type('user@example.com');
    cy.get('[data-testid="google-password-input"]').type('SecurePassword123!');

    // Click Google login button in modal
    cy.get('[data-testid="google-login-submit"]').click();

    // Intercept Google token exchange
    cy.intercept('POST', 'https://oauth2.googleapis.com/token').as('googleTokenExchange');
    cy.wait('@googleTokenExchange');

    // Verify user profile updates with Google info
    cy.get('[data-testid="profile-name"]').should('contain', 'User');
    cy.get('[data-testid="profile-email"]').should('contain', 'user@example.com');
    cy.get('[data-testid="google-connected-badge"]').should('be.visible');
    cy.get('[data-testid="google-connected-badge"]').should('contain', 'Connected');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Google account connected successfully');
  });

  it('should handle Google account connection failure with error message', () => {
    // Intercept Google OAuth redirect
    cy.intercept('GET', 'https://accounts.google.com/oosignin?client_id=*').as('googleAuth');

    // Click Google login button
    cy.get('[data-testid="google-login-button"]').click();

    // Wait for Google OAuth redirect
    cy.wait('@googleAuth');

    // Fill in invalid Google credentials
    cy.get('[data-testid="google-email-input"]').type('invalid-email@example.com');
    cy.get('[data-testid="google-password-input"]').type('WrongPassword123!');

    // Click Google login button in modal
    cy.get('[data-testid="google-login-submit"]').click();

    // Intercept Google token exchange with error response
    cy.intercept('POST', 'https://oauth2.googleapis.com/token', {
      statusCode: 401,
      body: { error: 'invalid_grant', error_description: 'Invalid credentials' }
    }).as('googleTokenExchangeError');

    cy.wait('@googleTokenExchangeError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Google login failed');

    // Verify Google connected badge is not visible
    cy.get('[data-testid="google-connected-badge"]').should('not.exist');

    // Verify user is still on profile page
    cy.get('[data-testid="profile-name"]').should('be.visible');
  });
});
